// ================== EDIT YOUR SETTINGS HERE ==================
const SETTINGS = {
  supabaseUrl: 'https://YOUR-PROJECT.supabase.co',   // Supabase -> Project Settings -> API -> Project URL
  claudeModel: 'claude-sonnet-5-5',
  openaiModel: 'gpt-5',                    // use the newest OpenAI model your key can access
  geminiModel: 'gemini-2.5-pro',           // use the newest Gemini model your key can access
  embeddingModel: 'text-embedding-3-small',// must be 1536-dim to match the database
  maxRevisions: 2,                         // feedback-loop limit
  passScore: 8,                            // critic score (1-10) needed to approve
  similarityThreshold: 0.85                // warn when new content is this similar to old
};
// Brand voice, audience, Aadu & Coco bible etc. come from the brand_context
// table (edit them in the Studio's Brand page, not here).
// ==============================================================

const f = $input.item.json;
const FORMATS = ['reel','short','post','carousel','story','long_video','guided_meditation','sleep_video','music','kids_story','coloring_page','article','recipe','script'];
const TRACKS = ['spiritual','kids','builder','lifestyle'];
const fmt = String(f.format || '').trim().toLowerCase();
const trk = String(f.track || '').trim().toLowerCase();
const st = parseInt(f.stage, 10);
const clean = v => (v === undefined || v === null || String(v).trim() === '' || String(v) === 'null') ? '' : String(v).trim();

const ctx = {
  ...SETTINGS,
  topic: clean(f.topic),
  track: TRACKS.includes(trk) ? trk : 'spiritual',
  format: FORMATS.includes(fmt) ? fmt : 'script',
  stage: st >= 1 && st <= 7 ? st : null,
  lengthNote: clean(f.length_note),
  notes: clean(f.notes),
  requestId: clean(f.request_id) || null,
  userId: clean(f.user_id) || null
};
ctx.audience = clean(f.audience) || (ctx.track === 'kids' ? 'children aged 4-8 and their parents'
  : ctx.track === 'builder' ? 'curious non-technical creators and solo founders interested in AI automation'
  : 'adults roughly 30-55 who function in ordinary life but have begun asking deeper questions');
if (!ctx.topic) throw new Error('A topic is required');
return { json: { ctx } };

const ctx = JSON.parse(JSON.stringify($('Config').first().json.ctx));
ctx.stages = $('Fetch Stages').all().map(i => i.json).filter(s => s && s.id);
const brand = $input.first().json || {};
ctx.brandContext = String(brand.content || '').trim();
ctx.brandSections = Number(brand.sections) || 0;
if (!ctx.brandContext) throw new Error('Brand context is empty - run db/002_brand_context.sql');
const fmtStage = s => `${s.id}. ${s.name} - "${s.core_question}" (${s.orientation})\n   Guidelines: ${s.content_guidelines}`;
const chosen = ctx.stages.find(s => s.id === ctx.stage);

if (ctx.track === 'builder') {
  ctx.stageGuide = chosen ? `Optional stage link:\n${fmtStage(chosen)}` : 'Stage framework not required (builder content about how the AI systems were built).';
} else if (chosen) {
  ctx.stageGuide = `TARGET STAGE:\n${fmtStage(chosen)}`;
} else {
  ctx.stageGuide = `STAGE: not specified. Choose the single most fitting stage from this seven-stage framework and follow its guidelines:\n${ctx.stages.map(fmtStage).join('\n')}`;
}

const FORMAT_GUIDE = {
  reel: '30-60 second vertical video built on ONE powerful observation: hook line (first 2 s) that names a recognisable experience, 4-7 short spoken lines, matching on-screen text, one closing question; then a visual direction, an Instagram caption that says what the account helps people understand and points to the related next post, and 5-8 hashtags.',
  short: '30-60 second YouTube Short built on ONE observation: hook naming a recognisable experience, 4-7 spoken lines, on-screen text, one closing question, title, and a pointer to the related longer video or series.',
  post: 'Instagram single-image post: one central idea, image concept in the brand visual style, caption (120-220 words) ending with a reflection question, 5-8 hashtags.',
  carousel: 'Instagram carousel (4:5): ONE main idea per slide, short readable text (max ~20 words per slide), slide count follows the content (usually 6-9). Adult structure: recognisable problem or question -> common interpretation -> deeper psychological explanation -> relatable example -> reframe -> reflection or next step. For each slide give the text and a one-line visual direction; then a caption and hashtags.',
  story: '3-5 Instagram story frames with text and an interaction (poll or question).',
  long_video: 'YouTube video script, 8-12 minutes: hook, intro, 3-5 sections with timestamps, practice, close, plus title, description and chapters.',
  guided_meditation: 'Spoken guided meditation script with [pause 5s] style markers, settling, main practice, gentle return. Plus title and description.',
  sleep_video: 'Very slow sleep meditation script with long [pause] markers, body relaxation, imagery, fading out. Plus title, description and visual scene prompts.',
  music: 'Music concept: mood, tempo, instruments, structure, and a prompt for an AI music tool. Lyrics only if original.',
  kids_story: 'Aadu & Coco story as an Instagram 4:5 carousel or picture book of 8-12 slides: one scene and one clear idea per slide (1-3 short sentences for a cream banner), plus a one-line illustration prompt per slide that restates the fixed character designs; the lesson emerges through choices and consequences; end with a gentle reflection question for children and parents.',
  coloring_page: '6-10 coloring page concepts: scene description, black-and-white line-art prompt, and one caption line each.',
  article: 'Article of 800-1200 words with headings and a practical takeaway.',
  recipe: 'Vegan recipe: ingredients with amounts, steps, prep time, and a mindful-eating note.',
  script: 'Clear, well-structured script suited to the requested format.'
};
ctx.formatGuide = FORMAT_GUIDE[ctx.format] || FORMAT_GUIDE.script;

const prompt = `ROLE: You are the PERCEPTION layer of a multi-agent content system for "Silent Witness".
Research the topic and produce an accurate, well-grounded brief.

TOPIC: ${ctx.topic}
TRACK: ${ctx.track}
FORMAT: ${ctx.format}
AUDIENCE: ${ctx.audience}
NOTES: ${ctx.notes || '-'}
${ctx.stageGuide}

Return:
1. Core concepts explained plainly
2. Relevant traditions, texts, teachers or sources (only attributions you are confident about; name the tradition)
3. Common misconceptions
4. Practical takeaways or exercises
5. Anything uncertain or disputed - flag it clearly`;

return [{ json: { ctx, body: {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  tools: [{ google_search: {} }]
} } }];

const ctx = JSON.parse(JSON.stringify($('Research Prompt').first().json.ctx));
const parts = $input.first().json.candidates?.[0]?.content?.parts || [];
ctx.research = parts.map(p => p.text || '').join('
').trim();
if (!ctx.research) throw new Error('Gemini research returned no text');

const body = {
  model: ctx.openaiModel,
  messages: [
    { role: 'system', content: 'You are the DIVERGENT-THINKING layer of a multi-agent content system. Generate bold, varied, original ideas. Do not self-censor; the executive filters later. Avoid cliches common in spiritual content.' },
    { role: 'user', content: `BRAND CONTEXT (stay within it):
${ctx.brandContext}

RESEARCH BRIEF:
${ctx.research}

TOPIC: ${ctx.topic}
FORMAT: ${ctx.format} - ${ctx.formatGuide}
AUDIENCE: ${ctx.audience}
${ctx.stageGuide}

Generate:
- 10 scroll-stopping hooks for the first seconds
- 3 distinct angles, each with a one-line pitch
- 5 title options
- 3 vivid stories, images or metaphors that make the core idea land
- 2 unusual, specific details that would make this piece unlike anything else on the topic` }
  ]
};
return [{ json: { ctx, body } }];

const j = $input.first().json;
let ctx;
if (j.choices) {
  // first pass: coming from ChatGPT
  ctx = JSON.parse(JSON.stringify($('Ideas Prompt').first().json.ctx));
  ctx.ideas = j.choices[0].message.content;
  ctx.iteration = 0;
  ctx.history = [];
} else {
  // revision pass: coming back from the critic loop
  ctx = JSON.parse(JSON.stringify(j.ctx));
  ctx.iteration += 1;
}

const kids = ctx.track === 'kids' ? '\nFollow the Aadu & Coco series bible exactly (character designs, lessons, two-layer storytelling, visual style). Very simple words, short sentences, warmth and gentle humour. No fear-based messages, no philosophy terms.' : '';
const builder = ctx.track === 'builder' ? '\nWrite in first person ("I built..."), honest about mistakes, step-by-step and non-technical-friendly. No hype.' : '';

let user = `RESEARCH BRIEF (facts - stay faithful to this):\n${ctx.research}

IDEAS (pick the strongest hook and angle; discard the rest):\n${ctx.ideas}

Write the final piece.
TOPIC: ${ctx.topic}
FORMAT: ${ctx.format} - ${ctx.formatGuide}
LENGTH: ${ctx.lengthNote || 'as suits the format'}
AUDIENCE: ${ctx.audience}
NOTES: ${ctx.notes || '-'}
${ctx.stageGuide}

BRAND CONTEXT (follow it - voice, audience, claims, formats, things to avoid):
${ctx.brandContext}${kids}${builder}

Follow the stage guidelines and brand context strictly. One central idea. Recognition before instruction: first articulate the reader's experience accurately, then offer the insight. Include at least one specific, original element (a precise observation, a fresh metaphor or an unusual practice) so the piece is not generic. Return only the finished piece.`;

if (ctx.iteration > 0) {
  user += `\n\n--- REVISION ROUND ${ctx.iteration} ---\nPREVIOUS DRAFT:\n${ctx.draft}\n\nCRITIC FEEDBACK (score ${ctx.score}/10):\n${ctx.feedback}\n\nRevise the draft to address every point. Return only the full revised piece.`;
}

const body = {
  model: ctx.claudeModel,
  max_tokens: 6000,
  system: 'You are the EXECUTIVE layer of the Silent Witness multi-agent content system. You integrate research and ideas into one coherent, original, high-quality piece and act precisely on critic feedback.',
  messages: [{ role: 'user', content: user }]
};
return [{ json: { ctx, body } }];

const ctx = JSON.parse(JSON.stringify($('Prepare Draft').first().json.ctx));
ctx.draft = ($input.first().json.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
if (!ctx.draft) throw new Error('Claude returned an empty draft');

const prompt = `ROLE: You are the ERROR-DETECTION layer of the Silent Witness content system. Be strict, specific and fair.

RESEARCH BRIEF (ground truth):\n${ctx.research}

${ctx.stageGuide}

FORMAT REQUIRED: ${ctx.format} - ${ctx.formatGuide}
AUDIENCE: ${ctx.audience}

BRAND CONTEXT (the standard to judge against):
${ctx.brandContext}

DRAFT TO REVIEW:\n${ctx.draft}

Score 1-10 overall. Check:
- Factual accuracy and correct attribution vs the brief.
- STAGE GUIDELINES (fail hard if it equates a glimpse or experience of oneness with lasting realization, makes guru-style claims, ranks people by stage, or spiritually bypasses real hardship).
- CLAIMS AND BOUNDARIES (fail hard if the framework or spiritual ideas are presented as science, or if it diagnoses anyone).
- Brand voice and the "things to avoid" table.
- One central idea; recognition before instruction; a clear reflection or next step.
- Format requirements (one idea per slide, readable text, sensible length).
- For Aadu & Coco: the lesson emerges through choices and consequences (not a lecture), the child is satisfied first, and illustration prompts keep the fixed character designs.
- Hook strength, clarity, emotional resonance, and originality (would this stand out from generic content on the topic?).

Also tag the piece for the content library.

Return JSON only:
{
  "score": number,
  "issues": [string],
  "feedback": "concrete, numbered revision instructions",
  "title": "best title for the piece",
  "summary": "1-2 sentence summary for an app card",
  "primary_stage": number 1-7 or null,
  "secondary_stages": [numbers 1-7],
  "themes": [2-5 short lowercase themes],
  "practices": [0-4 practices used, e.g. breathwork, body scan, self-inquiry, visualization],
  "traditions": [0-3 traditions referenced, e.g. Advaita, Buddhism, Stoicism],
  "uniqueness_note": "one sentence on what makes this piece original"
}`;

return [{ json: { ctx, body: {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: { responseMimeType: 'application/json', temperature: 0.2 }
} } }];

const ctx = JSON.parse(JSON.stringify($('Critic Prompt').first().json.ctx));
const raw = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
let critic;
try { critic = JSON.parse(raw.replace(/^```json\s*|```$/g, '')); }
catch (e) { critic = { score: 0, issues: ['Critic returned invalid JSON'], feedback: raw.slice(0, 1000) }; }

ctx.critic = critic;
ctx.score = Number(critic.score) || 0;
ctx.feedback = critic.feedback || '';
ctx.history.push({ round: ctx.iteration, score: ctx.score, issues: critic.issues || [] });

const done = ctx.score >= ctx.passScore || ctx.iteration >= ctx.maxRevisions;
return [{ json: { done, ctx } }];

const c = JSON.parse(JSON.stringify($input.first().json.ctx));
const k = c.critic || {};
const inRange = n => Number.isInteger(n) && n >= 1 && n <= 7;
const ints = a => (Array.isArray(a) ? a : []).map(Number).filter(inRange);
const strs = (a, max) => (Array.isArray(a) ? a : []).map(s => String(s).trim().toLowerCase()).filter(Boolean).slice(0, max);

let stage = c.stage || (inRange(Number(k.primary_stage)) ? Number(k.primary_stage) : null);
let feedback = c.feedback;
if (c.track === 'spiritual' && !stage) {
  stage = 4;   // required for spiritual content; flagged for you to verify
  feedback = '[Stage auto-set to 4 (Meaning) - please verify]\n' + (feedback || '');
}

const CHANNELS = {
  spiritual: ['long_video','guided_meditation','sleep_video','music'].includes(c.format) ? ['yt_meditation','app'] : ['instagram','app'],
  kids: c.format === 'coloring_page' ? ['amazon_kdp','instagram'] : ['instagram','app'],
  builder: ['long_video','script','short'].includes(c.format) ? ['yt_builder'] : ['yt_builder','instagram'],
  lifestyle: ['app','instagram']
};

const approved = c.score >= c.passScore;
const record = {
  title: String(k.title || c.topic).slice(0, 200),
  summary: k.summary || null,
  body: c.draft,
  track: c.track,
  format: c.format,
  primary_stage: stage,
  secondary_stages: ints(k.secondary_stages).filter(n => n !== stage),
  themes: strs(k.themes, 6),
  practices: strs(k.practices, 5),
  traditions: (Array.isArray(k.traditions) ? k.traditions : []).map(String).slice(0, 4),
  audience: c.track === 'kids' ? 'kids' : 'adults',
  language: 'en',
  status: approved ? 'in_review' : 'draft',
  critic_score: Math.max(0, Math.min(10, c.score)),
  critic_feedback: feedback,
  revision_rounds: c.iteration,
  uniqueness_note: k.uniqueness_note || null,
  ai_contributions: {
    research: 'gemini:' + c.geminiModel, ideas: 'openai:' + c.openaiModel,
    script: 'anthropic:' + c.claudeModel, critic: 'gemini:' + c.geminiModel,
    score_history: c.history.map(h => h.score),
    brand_sections: c.brandSections
  },
  synthetic_media: false,
  source_request_id: c.requestId,
  target_channels: CHANNELS[c.track] || ['app'],
  app_visible: false
};
if (c.userId) record.owner_id = c.userId;

return [{ json: { ctx: c, approved, body: record } }];

const c = $('Build Record').first().json.ctx;
const row = Array.isArray($input.first().json) ? $input.first().json[0] : $input.first().json;
if (!row || !row.id) throw new Error('Saving to the library failed: ' + JSON.stringify($input.first().json).slice(0, 300));
const text = [row.title, row.summary, row.body].filter(Boolean).join('\n\n').slice(0, 24000);
return [{ json: { ctx: c, itemId: row.id, body: { model: c.embeddingModel, input: text } } }];

const c = $('Build Record').first().json.ctx;
const itemId = $('Embed Prompt').first().json.itemId;
const similar = $input.all().map(i => i.json).filter(s => s && s.id && s.id !== itemId);
const stageName = (c.stages || []).find(s => s.id === ($('Build Record').first().json.body.primary_stage))?.name || null;
return [{ json: {
  saved_to_library: true,
  content_item_id: itemId,
  title: $('Build Record').first().json.body.title,
  stage: stageName,
  status: $('Build Record').first().json.body.status,
  approved_by_critic: c.score >= c.passScore,
  critic_score: c.score,
  revision_rounds: c.iteration,
  score_history: c.history.map(h => `round ${h.round}: ${h.score}/10`).join(', '),
  similar_existing: similar.length
    ? similar.map(s => `${s.title} (${Math.round(s.similarity * 100)}% similar)`).join('; ')
    : 'none',
  script: c.draft
} }];
